from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    keep = {color for color, count in counts.items() if color != background and count >= 8}
    out = [[background for _ in range(w)] for _ in range(h)]
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or color not in keep or (r,c) in seen:
                continue
            stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for ny,nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=ny<h and 0<=nx<w and (ny,nx) not in seen and grid[ny][nx]==color:
                        seen.add((ny,nx)); stack.append((ny,nx))
            if len(cells) >= 6:
                r0=min(y for y,x in cells); r1=max(y for y,x in cells)
                c0=min(x for y,x in cells); c1=max(x for y,x in cells)
                for y in range(r0,r1+1):
                    for x in range(c0,c1+1): out[y][x]=color
    return out
